import { useState, KeyboardEvent, ChangeEvent } from 'react';
import { TextField, Tag, Stack } from '@jinx-ui/react';

interface TagInputProps {
  onChange?: (tags: string[]) => void;
  placeholder?: string;
}

export default function TagInput({ onChange, placeholder = 'Введите тег и нажмите Enter' }: TagInputProps) {
  const [tags, setTags] = useState<string[]>([]);
  const [inputValue, setInputValue] = useState('');

  const commitTags = (nextTags: string[]) => {
    setTags(nextTags);
    onChange?.(nextTags);
  };

  const addTag = (rawValue: string) => {
    const value = rawValue.trim();
    if (!value) return;
    if (tags.includes(value)) {
      setInputValue('');
      return;
    }
    commitTags([...tags, value]);
    setInputValue('');
  };

  const removeTag = (tagToRemove: string) => {
    commitTags(tags.filter((tag) => tag !== tagToRemove));
  };

  const handleInputChange = (event: ChangeEvent<HTMLInputElement>) => {
    setInputValue(event.target.value);
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter' || event.key === ',') {
      event.preventDefault();
      addTag(inputValue);
      return;
    }

    if (event.key === 'Backspace' && inputValue === '' && tags.length > 0) {
      commitTags(tags.slice(0, -1));
    }
  };

  const handleBlur = () => {
    if (inputValue.trim()) {
      addTag(inputValue);
    }
  };

  return (
    <Stack direction="column" gap="var(--jx-space-2)" className="jx-tag-input">
      <TextField
        value={inputValue}
        onChange={handleInputChange}
        onKeyDown={handleKeyDown}
        onBlur={handleBlur}
        placeholder={placeholder}
        aria-label="Добавить тег статьи"
      />
      {tags.length > 0 && (
        <Stack
          direction="row"
          gap="var(--jx-space-1)"
          wrap="wrap"
          role="list"
          aria-label="Выбранные теги"
        >
          {tags.map((tag) => (
            <Tag
              key={tag}
              role="listitem"
              onRemove={() => removeTag(tag)}
              removable
            >
              {tag}
            </Tag>
          ))}
        </Stack>
      )}
    </Stack>
  );
}

